// Espaco de flag acrescentado em 05/08/2026, de uma vez so e de proposito.
//
// Motivo: os 190 FLAG_HIDDEN_ITEM_* de Kanto vinham definidos como 0 no
// upstream, porque numa build Emerald Kanto nao existia. Com as cinco regioes
// na mesma ROM eles passam a valer, e flag 0 faz o montador abortar com
// "Hidden Item flag 0 is too small".
//
// Crescer FLAGS_COUNT empurra tudo que vem depois de flags[] dentro do
// SaveBlock1 e INVALIDA save existente. Por isso foi feito agora, antes de
// existir save para proteger, e com a reserva de Unova ja inclusa: fazer de
// novo depois custaria a save do jogador.
//
// Teto: SaveBlock1 ocupa os setores 1 a 4, 15872 B. Conferido por
// dev_scripts/guarda_save.py a cada verificacao.
#define FLAG_HIDDEN_ITEMS_FRLG_START                (DAILY_FLAGS_END + 1)
#define NUM_HIDDEN_ITEMS_FRLG                       0xBE // 190, os de Kanto e Sevii

// Reserva para os itens de Unova (334 item balls + 133 escondidos = 467).
// Reservado agora mesmo sem estar em uso, porque so ha uma janela barata.
#define FLAG_ITEMS_UNOVA_START                      (FLAG_HIDDEN_ITEMS_FRLG_START + NUM_HIDDEN_ITEMS_FRLG)
#define NUM_ITEMS_UNOVA                             0x1D3 // 467

// Reserva de historia, aberta em 12/08/2026 dentro da janela de quebra de save
// que o Gui reabriu para a revisao daquele dia.
//
// Motivo, medido e nao chutado: o pool tinha 40 flags realmente livres
// (dev_scripts/flags_livres.py) e a fila de trabalho pede centenas. As 209 cenas
// de Unova, os 230 itens escondidos que faltam em Sinnoh, o resto da Galactica e
// os puzzles de ginasio das cinco regioes somam algo em torno de 1100 flags. A
// reserva e de 2048 de proposito: crescer o pool INVALIDA a save, hoje isso e
// permitido e amanha custa a partida do Gui, entao errar para cima e a decisao
// barata. Cada 8 flags custam 1 byte de SaveBlock1, e 2048 custam 256 B.
//
// Elas sao declaradas uma a uma, e nao como faixa, por dois motivos: e o padrao
// que o repo ja usa para flag livre, e `flags_livres.py` so enxerga o que existe
// como `#define FLAG_UNUSED_0xNNN`. Faixa declarada em bloco seria pool
// invisivel para a ferramenta que distribui flag entre agentes.
//
// Como usar: nunca escreva o numero. Apelide, que e o que marca a flag como
// ocupada aos olhos do flags_livres.py:
//
//     #define FLAG_MINHA_CENA_DE_UNOVA   FLAG_UNUSED_0x1831
//
// O sufixo hexadecimal do nome e o valor de verdade da flag nesta build
// (0x1831 = 6193 = FLAG_ITEMS_UNOVA_START + NUM_ITEMS_UNOVA). Ele deixa de casar
// se alguem mexer em MAX_TRAINERS_COUNT de novo, exatamente como ja acontece com
// os nomes herdados do pokeemerald: o nome e um identificador, o valor quem
// resolve e o pre-processador.
#define FLAG_RESERVA_HISTORIA_START                 (FLAG_ITEMS_UNOVA_START + NUM_ITEMS_UNOVA)
#define NUM_RESERVA_HISTORIA                        0x800 // 2048

