// ponytail: viagem entre regioes. Cada Elite dos Quatro derrotada liga a flag da
// regiao seguinte, e o marinheiro do cais monta o menu de destinos lendo estas
// tres. Ida e volta sem gastar var: a flag ja diz tudo que o menu precisa saber.
// RESERVADAS. Nao reutilizar para outra coisa, ver Pokemon Claude/SINNOH-PADRAO.md
#define FLAG_REGIAO_JOHTO_LIBERADA   FLAG_UNUSED_0x022
#define FLAG_REGIAO_HOENN_LIBERADA   FLAG_UNUSED_0x023
#define FLAG_REGIAO_SINNOH_LIBERADA  FLAG_UNUSED_0x024


// Trio de iniciais por regiao (decisao 68). Uma flag por LABORATORIO, e nao a
// FLAG_SYS_POKEMON_GET, porque com a ordem cronologica (decisao 66) quem acende
// a FLAG_SYS_POKEMON_GET e o Oak, em Kanto: dai em diante ela ja esta acesa, e
// as Poke Bolas dos laboratorios seguintes NAO NASCERIAM (o campo "flag" do
// object_event esconde o objeto quando a flag esta ligada). Medido, nao suposto:
// data/maps/SandgemTown_House1/map.json usava FLAG_SYS_POKEMON_GET nas tres
// bolas do ROWAN, e o inicial de Sinnoh sumia depois que Kanto virou a regiao 1.
//
// Kanto continua com FLAG_SYS_POKEMON_GET (e a primeira regiao, a flag esta
// apagada quando o jogador chega la) e Hoenn continua com
// FLAG_HIDE_ROUTE_101_BIRCH_STARTERS_BAG, que ja e so dela.
#define FLAG_INICIAL_JOHTO   FLAG_UNUSED_0x054
#define FLAG_INICIAL_SINNOH  FLAG_UNUSED_0x055
#define FLAG_INICIAL_UNOVA   FLAG_UNUSED_0x4EF


// Insignias de HOENN, decisao do Gui de 12/08/2026 (bloco B5, opcao "a").
//
// O comentario logo abaixo, de Sinnoh, dizia que FLAG_BADGE01_GET..08 "continuam
// de Hoenn". Deixou de ser verdade e a linha foi corrigida: as oito do MOTOR
// passam a ser as de KANTO, que e a primeira regiao da ordem cronologica
// (decisao 66) e portanto quem deve destravar HM e obediencia. Medido em
// 12/08/2026, antes da troca: os oito ginasios de Kanto e os oito de Hoenn
// acendiam exatamente as mesmas oito flags, entao quem terminava Kanto chegava
// em Hoenn com as oito insignias de Hoenn no bolso e a obediencia ja destravada
// por inteiro (src/battle_util.c:5589).
//
// LIMITE, de proposito: `FLAG_BADGE01_GET`..`08` continuam sendo as unicas que o
// MOTOR le (obediencia, `sLevelCapFlagMap` em src/caps.c, o placar de insignias
// de src/battle_script_commands.c:9959). As oito abaixo sao so de CONTEUDO: quem
// as le e script de Hoenn (estatua de ginasio, guarda da Liga, Casa da Manha da
// Rota 110, mae do jogador, Scott, Lilycove). Nada em src/ foi tocado.
#define FLAG_INSIGNIA_HOENN_1  FLAG_UNUSED_0x2028  // Roxanne,       Rustboro
#define FLAG_INSIGNIA_HOENN_2  FLAG_UNUSED_0x2029  // Brawly,        Dewford
#define FLAG_INSIGNIA_HOENN_3  FLAG_UNUSED_0x202A  // Wattson,       Mauville
#define FLAG_INSIGNIA_HOENN_4  FLAG_UNUSED_0x202B  // Flannery,      Lavaridge
#define FLAG_INSIGNIA_HOENN_5  FLAG_UNUSED_0x202C  // Norman,        Petalburg
#define FLAG_INSIGNIA_HOENN_6  FLAG_UNUSED_0x202D  // Winona,        Fortree
#define FLAG_INSIGNIA_HOENN_7  FLAG_UNUSED_0x202E  // Tate e Liza,   Mossdeep
#define FLAG_INSIGNIA_HOENN_8  FLAG_UNUSED_0x202F  // Juan,          Sootopolis

// ponytail: bloco B6, cenas da Equipe Galactica de Sinnoh que faltavam
// (dev_scripts/cena_galactica_sinnoh.py, 12/08/2026). Faixa exclusiva desta
// frente: FLAG_UNUSED_0x1900 a 0x19FF. Gastas 11; sobram 245.
//
// Cada uma e o campo `flag` de um `object_event` de cena: o motor so cria o
// objeto quando `!FlagGet(flagId)` (src/event_object_movement.c:2882). Quem as
// acende e um MAP_SCRIPT_ON_TRANSITION, que roda ANTES de InitMap()
// (src/overworld.c), entao a leitura ja vale para o mesmo carregamento. Zero
// var: o marco de cada cena e a flag de "ja derrotei" que o motor grava sozinho
// para o treinador-gatilho. Precedente no repo: EternaCity_OnTransition.
#define FLAG_GALACTICA_MT_CORONET  FLAG_UNUSED_0x1900  // some quando o Cyrus cai no Spear Pillar
#define FLAG_GALACTICA_QG_TOMADO   FLAG_UNUSED_0x1901  // some quando o Saturn cai na sala de controle
// As duas de baixo NAO sao historia: no Platinum o mesmo NPC tem uma versao que
// luta e uma que nao, trocadas por GetTimeOfDay (scripts_route_210_south.s:15 e
// scripts_route_212_south.s:15). Aqui o ON_TRANSITION acende a flag e so a apaga
// na faixa de hora certa, nessa ordem: falha de leitura de hora deixa o
// treinador AUSENTE, nunca plantado no meio da rota.
#define FLAG_SINNOH_ROUTE210_WYATT_ESCONDIDO FLAG_UNUSED_0x1902  // Jogger Wyatt, so de manha
#define FLAG_SINNOH_ROUTE212_DANNY_ESCONDIDO FLAG_UNUSED_0x1903  // Policeman Danny, so de noite

// ponytail: as quatro cenas que fechavam a espinha da Galactica (12/08/2026).
// Duas destas nascem ACESAS, em EventScript_ResetAllMapFlags: o objeto que so
// deve aparecer no meio da historia precisa comecar escondido, e flag de jogo
// novo nasce APAGADA. As outras quatro nascem apagadas e a cena as acende.
#define FLAG_GALACTICA_CELESTIC          FLAG_UNUSED_0x1904  // o grunt da bomba caiu: some ele e o show da Rota 218
#define FLAG_CELESTIC_CYNTHIA_ESCONDIDA  FLAG_UNUSED_0x1905  // ACESA no jogo novo; a Cynthia so aparece depois do grunt
#define FLAG_GALACTICA_LAGO_VERITY       FLAG_UNUSED_0x1906  // a Mars caiu: somem ela e os quatro grunts do lago
#define FLAG_ESCONDE_LAGO_ACUITY         FLAG_UNUSED_0x1907  // ACESA no jogo novo; Jupiter e o rival so aparecem depois da Mars
#define FLAG_GALACTICA_ACUITY_VISTO      FLAG_UNUSED_0x1908  // a cena do Lago Acuity ja rodou, e nao repete
#define FLAG_GALACTICA_CANALAVE_RIVAL    FLAG_UNUSED_0x1909  // o rival de Canalave ja foi batido

// ponytail: bloco B6, leva 15/08/2026 (dev_scripts/fila_b6.json). Uma flag so:
