// Os 109 atendentes de Wi-Fi, Union Room, Colosseum e Group Connection dos
// Pokemon Center de Sinnoh (2F e B1F). No Platinum o `script` deles nao aponta
// para o arquivo do mapa: cai nas faixas SCRIPT_ID_OFFSET_POKEMON_CENTER_2F_
// COMMON (9000), _B1F_COMMON (9200) e GROUP_CONNECTION (9300), que sao o
// sistema de comunicacao do DS. Esta ROM e um GBA de um cartucho so: nao existe
// Wi-Fi, nem Union Room, nem sala de troca subterranea. Decisao do dono do
// projeto, 12/08/2026 (pergunta 17): ESCONDER, nao inventar fala substituta.
//
// Apagar continua proibido (e gente da fonte, e a save guarda INDICE de
// object_event), entao vale o mesmo mecanismo do clone duplicado: a flag vai no
// campo "flag" do objeto e `src/event_object_movement.c:2882` so cria o objeto
// quando `!FlagGet(flagId)`. Acesa uma vez em EventScript_ResetAllMapFlags
// (data/scripts/new_game.inc). Reversivel: apagar a flag traz os 109 de volta,
// mudos, que e exatamente o estado de antes.
#define FLAG_SINNOH_WIFI_ESCONDIDO FLAG_UNUSED_0x1831

// O "ja recebi" da Good Rod do pescador da Route 209, primeira cena portada do
// bloco B6 (data/maps/Route209/scripts.inc). Ela NAO entra em
// EventScript_ResetAllMapFlags: apagada e o estado de jogo novo, e a cena a
// acende quando o jogador aceita a vara. Nao reusa FLAG_RECEIVED_GOOD_ROD
// porque aquela e do pescador da Route 118, de HOENN, e as duas cenas sao
// independentes; quem ja pegou a vara la e barrado pelo `checkitem` da cena.
#define FLAG_RECEBEU_GOOD_ROD_SINNOH FLAG_UNUSED_0x1832

