// Duas flags do topo da faixa órfã 0x4DB a 0x4EE, conferida livre por
// dev_scripts/flags_livres.py em 16/08/2026. Ficam no TOPO de propósito: a
// frente de Unova aloca subindo a partir de 0x4C3 (hoje em 0x4DA), então usar
// o fim da faixa deixa o máximo de espaço para ela. Apelidar flag existente
// não mexe em FLAGS_COUNT, ou seja, não invalida save.
#define FLAG_SEM_ENCONTRO_SELVAGEM                     FLAG_UNUSED_0x4EE
#define FLAG_EXP_ALL                                   FLAG_UNUSED_0x4ED
// <<< Conveniências do jogador (item infinito, EXP ALL) <<<

// >>> B6 Sinnoh, flags dos grupos de hidden_flag (dev_scripts/maquina_sinnoh.py) >>>
// DONO DA FAIXA 0x1B00 a 0x1BFF: a obra de Sinnoh
// (PLANO-OBRAS-SINNOH.md, bloco S1). Uma flag por grupo de
// hidden_flag da fonte, nome mecanico da decisao 9.
