// Por que NAO e a faixa 0x190B-0x19FF que o plano reservou: em
// 17/08/2026 a consolidacao de Kanto (652776174a) apelidou os 245
// enderecos dela e seguiu ate 0x1A4B (medido por
// dev_scripts/flags_livres.py). 0x1A00-0x1AFF e reserva de Unova,
